 2→import type { TableInfo } from '../types';
 3→import './Sidebar.css';
 4→
 5→interface SidebarProps {
 6→  tables: TableInfo[];
 7→  onTableClick: (tableName: string) => void;
 8→  onTableDelete: (tableName: string) => void;
 9→  collapsed: boolean;
10→  onToggle: () => void;
11→}
12→
13→export function Sidebar({ tables, onTableClick, onTableDelete, collapsed, onToggle }: SidebarProps) {
14→  const [expanded, setExpanded] = useState<Record<string, boolean>>({});
15→
16→  const toggle = (name: string) => {
17→    setExpanded((prev) => ({ ...prev, [name]: !prev[name] }));
18→  };
19→
20→  return (
21→    <div className={`sidebar ${collapsed ? 'sidebar--collapsed' : ''}`}>
22→      <div className="sidebar__header">
23→        <h3 className="sidebar__title">Tables</h3>
24→        <button
25→          className="sidebar__collapse-toggle"
26→          onClick={onToggle}
27→          aria-label={collapsed ? 'Expand sidebar' : 'Collapse sidebar'}
28→        >
29→          <span className="sidebar__hamburger" />
30→        </button>
31→      </div>
32→      <div className="sidebar__content">
33→        {tables.length === 0 && (
34→          <p className="sidebar__empty">No tables yet. Upload a CSV to get started.</p>
35→        )}
36→        <ul className="sidebar__list">
37→          {tables.map((table) => (
38→            <li key={table.name} className="sidebar__item">
39→              <div className="sidebar__table-header">
40→                <button
41→                  className="sidebar__toggle"
42→                  onClick={() => toggle(table.name)}
43→                >
44→                  {expanded[table.name] ? '\u25BC' : '\u25B6'}
45→                </button>
46→                <button
47→                  className="sidebar__table-name"
48→                  onClick={() => onTableClick(table.name)}
49→                  title={`SELECT * FROM "${table.name}" LIMIT 100`}
50→                >
51→                  {table.name}
52→                </button>
53→                <span className="sidebar__row-count">
54→                  {table.rowCount} row{table.rowCount !== 1 ? 's' : ''}
55→                </span>
56→                <button
57→                  className="sidebar__delete"
58→                  onClick={(e) => {
59→                    e.stopPropagation();
60→                    onTableDelete(table.name);
61→                  }}
62→                  title={`Delete table "${table.name}"`}
63→                  aria-label={`Delete table ${table.name}`}
64→                >
65→                  🗑
66→                </button>
67→              </div>
68→              {expanded[table.name] && (
69→                <ul className="sidebar__columns">
70→                  {table.columns.map((col) => (
71→                    <li key={col.name} className="sidebar__column">
72→                      <span className="sidebar__col-name">{col.name}</span>
73→                      <span className="sidebar__col-type">{col.type}</span>
74→                    </li>
75→                  ))}
76→                </ul>
77→              )}
78→            </li>
79→          ))}
80→        </ul>
81→      </div>
82→    </div>
83→  );
84→}
